def obj(properties):
    return {'type': 'object', 'properties': properties, 'required': list(properties), 'additionalProperties': False}


def tool_definitions():
    request = deepcopy(REQUEST)
    definitions = request.pop('$defs')
    for key in ('$id', '$schema', 'title'):
        request.pop(key, None)
    pin = {'$ref': '#/$defs/pin'}
    nullable_pin = {'oneOf': [pin, {'type': 'null'}]}
    statuses = ['rule_pin_not_current', 'missing_binding', 'fact_not_supplied',
                'fact_pin_not_current', 'fact_withdrawn', 'predicate_mismatch', 'exact_match']
    row = obj({'requirement_id': deepcopy(definitions['pin']['properties']['id']),
               'status': {'enum': statuses}, 'required_predicate': {'$ref': '#/$defs/predicate'},
               'bound_fact': nullable_pin, 'current_fact': nullable_pin})
    report = obj({'schema': {'const': 'foundation-math-hypothesis-scope/1/report'},
                  'input_sha256': deepcopy(definitions['pin']['properties']['revision_sha256']),
                  'rule': pin, 'current_rule': pin, 'all_requirements_matched': {'type': 'boolean'},
                  'requirements': {'type': 'array', 'items': row, 'minItems': 1, 'maxItems': 32},
                  'semantics': {'const': 'exact_authored_premise_matching_only'},
                  **{key: {'const': False} for key in ('fact_truth_checked', 'rule_soundness_checked',
                     'geometry_checked', 'runtime_acceptance', 'lean_proof')}})
    common = {'schema_version': {'const': 1}, 'scope': {'const': 'exact_authored_premise_matching_only'},
              'truth_assessment': {'const': 'not_assessed'},
              **{key: {'const': False} for key in ('formal_proof', 'runtime_goal_acceptance',
                 'fact_truth_checked', 'rule_soundness_checked', 'geometry_checked')}}
    success = obj({**common, 'status': {'const': 'success'}, 'result': report})
    error = obj({**common, 'status': {'const': 'error'}, 'error': obj({
        'code': {'type': 'string'}, 'path': {'type': 'string'}, 'message': {'type': 'string'}})})
    output = obj({'tool': {'const': 'match_hypothesis_scope'},
                  'assessment': {'enum': ['authored_premise_scope_compared', 'tool_error']},
                  'formal_proof': {'const': False}, 'runtime_goal_acceptance': {'const': False},
                  'receipt': {'oneOf': [success, error]}})
    output['allOf'] = [{'if': {'properties': {'receipt': {'properties': {'status': {'const': 'success'}}}}},
                        'then': {'properties': {'assessment': {'const': 'authored_premise_scope_compared'}}},
                        'else': {'properties': {'assessment': {'const': 'tool_error'}}}}]
    draft = 'https://json-schema.org/draft/2020-12/schema'
    return [{'name': 'match_hypothesis_scope', 'readOnly': True,
             'description': 'Compare explicit exact current fact bindings with caller-authored typed requirements. '
             'A fact is a supplied assertion, not verified knowledge; provenance and context digests are opaque, '
             'not fetched, authenticated or validated. Exact match does not establish truth, geometry, adequate '
             'hypotheses, rule soundness, or a conclusion. No inference, weakening, ledger lookup, repinning, '
             'formal proof or runtime acceptance. At most 64 objects, maps and facts; 32 requirements and bindings. '
             'Bridge retains 65536 input bytes including envelope, 1048576 output bytes and 16384 JSON nodes; '
             'the matcher also enforces its stricter field, depth, type and output budgets. '
             'No paths, commands, code, network, models or caller limits.',
             'inputSchema': {'$schema': draft, **obj({'document': request}), '$defs': deepcopy(definitions)},
             'outputSchema': {'$schema': draft, **output, '$defs': deepcopy(definitions)}}]
